// v06 sound design: VO + 4 music bands (frequency-aware ducking) + SFX grouped by delivery stem.
// All levels/timings live in sound_v06.json (generated by tools/make_sound_v06.py; edit gains there).
import React from 'react';
import {Sequence, interpolate, staticFile} from 'remotion';
import {Audio} from '@remotion/media';
import cues from './cues.json';
import sd from './sound_v06.json';

const A = (n: string) => staticFile(`audio_v06/${n}.wav`);
type Band = 'music_low' | 'music_mid' | 'music_air' | 'music_fx';
export const GROUP_GAIN: Record<string, number> = {vo: 1, music: 1, opening: 1, typographic: 1, coin: 1, gear: 1, transition: 1, ui: 1, bomb: 1};

/** speech envelope 0..1 (attack 3 f, release 8 f) */
export const speechAt = (f: number) => {
  let d = 0;
  for (const [a, b] of cues.speech as [number, number][]) {
    const att = interpolate(f, [a - 3, a], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
    const rel = interpolate(f, [b, b + 8], [1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
    d = Math.max(d, Math.min(att, rel));
  }
  return d;
};
export const bandGain = (b: Band, f: number) => {
  const g = (sd.music.gain as Record<Band, number>)[b];
  const k = (sd.music.duck as Record<Band, number>)[b];
  return GROUP_GAIN.music * g * (1 - (1 - k) * speechAt(f));
};

export const AudioMixV06: React.FC = () => (
  <>
    <Audio src={A('vo_clean')} volume={GROUP_GAIN.vo} />
    {(sd.music.bands as Band[]).map((b) => (
      <Audio key={b} src={A(b)} volume={(f) => bandGain(b, f)} />
    ))}
    {(sd.place as [string, string, number, number][]).map(([group, name, t, gain], i) => (
      <Sequence key={i} from={Math.round(t * 30)} layout="none" name={`${group}:${name}`}>
        <Audio src={A(`sfx_${name}`)} volume={gain * (GROUP_GAIN[group] ?? 1)} />
      </Sequence>
    ))}
  </>
);
